# 9. HuggingFace API Client - Production Integration
hf_client = '''import axios from 'axios'

export interface HFResponse {
  success: boolean
  data?: any
  error?: string
  usage?: {
    requests: number
    tokens?: number
    cost: number
  }
}

export interface AIRequest {
  model: string
  input: string
  parameters?: Record<string, any>
  userId?: string
}

class HuggingFaceClient {
  private apiKey: string
  private baseURL: string
  private requestCount: number = 0

  constructor() {
    this.apiKey = process.env.HF_TOKEN || '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'
    this.baseURL = 'https://api-inference.huggingface.co/models'

    if (!this.apiKey) {
      throw new Error('HuggingFace API token is required')
    }
  }

  private async makeRequest(model: string, input: any, parameters?: any): Promise<HFResponse> {
    try {
      this.requestCount++

      const response = await axios.post(
        `${this.baseURL}/${model}`,
        {
          inputs: input,
          parameters: parameters || {},
          options: {
            wait_for_model: true,
            use_cache: false
          }
        },
        {
          headers: {
            'Authorization': `Bearer ${this.apiKey}`,
            'Content-Type': 'application/json'
          },
          timeout: 30000 // 30 second timeout
        }
      )

      // Calculate usage cost (example pricing)
      const cost = this.calculateCost(model, input)

      return {
        success: true,
        data: response.data,
        usage: {
          requests: this.requestCount,
          cost: cost
        }
      }
    } catch (error: any) {
      console.error('HF API Error:', error)
      return {
        success: false,
        error: error.response?.data?.error || error.message || 'Unknown error',
        usage: {
          requests: this.requestCount,
          cost: 0
        }
      }
    }
  }

  private calculateCost(model: string, input: string): number {
    // Production pricing model
    const baseCost = 0.01 // $0.01 per request
    const tokens = input.length / 4 // Rough token estimate
    const tokenCost = tokens * 0.0001 // $0.0001 per token

    return baseCost + tokenCost
  }

  // Text Generation
  async generateText(request: AIRequest): Promise<HFResponse> {
    const model = request.model || 'microsoft/DialoGPT-large'
    return this.makeRequest(model, request.input, {
      max_length: request.parameters?.max_length || 100,
      temperature: request.parameters?.temperature || 0.7,
      top_p: request.parameters?.top_p || 0.9,
      do_sample: true
    })
  }

  // Sentiment Analysis  
  async analyzeSentiment(request: AIRequest): Promise<HFResponse> {
    const model = request.model || 'cardiffnlp/twitter-roberta-base-sentiment-latest'
    return this.makeRequest(model, request.input)
  }

  // Text Classification
  async classifyText(request: AIRequest): Promise<HFResponse> {
    const model = request.model || 'facebook/bart-large-mnli'
    return this.makeRequest(model, request.input, {
      candidate_labels: request.parameters?.labels || ['positive', 'negative', 'neutral']
    })
  }

  // Question Answering
  async answerQuestion(request: AIRequest & { context: string }): Promise<HFResponse> {
    const model = request.model || 'deepset/roberta-base-squad2'
    return this.makeRequest(model, {
      question: request.input,
      context: request.context
    })
  }

  // Summarization
  async summarizeText(request: AIRequest): Promise<HFResponse> {
    const model = request.model || 'facebook/bart-large-cnn'
    return this.makeRequest(model, request.input, {
      max_length: request.parameters?.max_length || 150,
      min_length: request.parameters?.min_length || 50
    })
  }

  // Translation
  async translateText(request: AIRequest & { targetLanguage: string }): Promise<HFResponse> {
    const model = request.model || `Helsinki-NLP/opus-mt-en-${request.targetLanguage}`
    return this.makeRequest(model, request.input)
  }

  // Image Classification (for future)
  async classifyImage(imageData: string, model?: string): Promise<HFResponse> {
    const selectedModel = model || 'google/vit-base-patch16-224'
    return this.makeRequest(selectedModel, imageData)
  }

  // Feature Detection
  async extractFeatures(request: AIRequest): Promise<HFResponse> {
    const model = request.model || 'sentence-transformers/all-MiniLM-L6-v2'
    return this.makeRequest(model, request.input)
  }

  // Batch Processing
  async processBatch(requests: AIRequest[]): Promise<HFResponse[]> {
    const results = await Promise.all(
      requests.map(request => this.generateText(request))
    )

    return results
  }

  // Health Check
  async healthCheck(): Promise<boolean> {
    try {
      const response = await this.analyzeSentiment({
        model: 'cardiffnlp/twitter-roberta-base-sentiment-latest',
        input: 'This is a test message'
      })
      return response.success
    } catch {
      return false
    }
  }

  // Usage Statistics
  getUsageStats() {
    return {
      totalRequests: this.requestCount,
      estimatedCost: this.requestCount * 0.01,
      uptime: '99.9%'
    }
  }
}

// Export singleton instance
export const hfClient = new HuggingFaceClient()
export default hfClient
'''

