# 10. HuggingFace API Route - Production Backend
hf_api_route = '''import { NextRequest, NextResponse } from 'next/server'
import { hfClient } from '@/lib/hf-client'
import { rateLimit } from '@/lib/rate-limit'

// Rate limiting configuration
const limiter = rateLimit({
  interval: 60 * 1000, // 1 minute
  uniqueTokenPerInterval: 500, // Max 500 unique tokens per minute
})

export async function POST(request: NextRequest) {
  try {
    // Rate limiting check
    const identifier = request.ip ?? 'anonymous'
    const { success } = await limiter.check(identifier, 10) // 10 requests per minute per IP

    if (!success) {
      return NextResponse.json(
        { 
          success: false, 
          error: 'Rate limit exceeded. Please try again later.',
          retryAfter: 60
        },
        { status: 429 }
      )
    }

    const body = await request.json()
    const { action, model, input, parameters, context, targetLanguage } = body

    if (!action || !input) {
      return NextResponse.json(
        { 
          success: false, 
          error: 'Action and input are required' 
        },
        { status: 400 }
      )
    }

    let result

    // Route to appropriate AI function
    switch (action) {
      case 'generate':
        result = await hfClient.generateText({ model, input, parameters })
        break

      case 'sentiment':
        result = await hfClient.analyzeSentiment({ model, input, parameters })
        break

      case 'classify':
        result = await hfClient.classifyText({ model, input, parameters })
        break

      case 'question':
        if (!context) {
          return NextResponse.json(
            { 
              success: false, 
              error: 'Context is required for question answering' 
            },
            { status: 400 }
          )
        }
        result = await hfClient.answerQuestion({ model, input, parameters, context })
        break

      case 'summarize':
        result = await hfClient.summarizeText({ model, input, parameters })
        break

      case 'translate':
        if (!targetLanguage) {
          return NextResponse.json(
            { 
              success: false, 
              error: 'Target language is required for translation' 
            },
            { status: 400 }
          )
        }
        result = await hfClient.translateText({ model, input, parameters, targetLanguage })
        break

      case 'features':
        result = await hfClient.extractFeatures({ model, input, parameters })
        break

      case 'batch':
        if (!Array.isArray(input)) {
          return NextResponse.json(
            { 
              success: false, 
              error: 'Batch processing requires an array of inputs' 
            },
            { status: 400 }
          )
        }
        const requests = input.map(item => ({ model, input: item, parameters }))
        result = await hfClient.processBatch(requests)
        break

      case 'health':
        const isHealthy = await hfClient.healthCheck()
        result = { 
          success: true, 
          data: { 
            status: isHealthy ? 'healthy' : 'unhealthy',
            timestamp: new Date().toISOString(),
            ...hfClient.getUsageStats()
          }
        }
        break

      default:
        return NextResponse.json(
          { 
            success: false, 
            error: `Unknown action: ${action}. Available actions: generate, sentiment, classify, question, summarize, translate, features, batch, health` 
          },
          { status: 400 }
        )
    }

    // Add revenue tracking
    if (result.usage) {
      result.usage.timestamp = new Date().toISOString()
      result.usage.userId = request.headers.get('x-user-id') || 'anonymous'
      result.usage.ip = identifier
    }

    return NextResponse.json(result)

  } catch (error: any) {
    console.error('HF API Route Error:', error)

    return NextResponse.json(
      { 
        success: false, 
        error: 'Internal server error',
        details: process.env.NODE_ENV === 'development' ? error.message : undefined
      },
      { status: 500 }
    )
  }
}

export async function GET(request: NextRequest) {
  try {
    // Health check endpoint
    const isHealthy = await hfClient.healthCheck()
    const stats = hfClient.getUsageStats()

    return NextResponse.json({
      success: true,
      data: {
        status: isHealthy ? 'operational' : 'degraded',
        timestamp: new Date().toISOString(),
        version: '1.0.0',
        endpoints: [
          'POST /api/hf-proxy - AI processing',
          'GET /api/hf-proxy - Health check'
        ],
        ...stats
      }
    })

  } catch (error: any) {
    return NextResponse.json(
      { 
        success: false, 
        error: 'Health check failed',
        timestamp: new Date().toISOString()
      },
      { status: 503 }
    )
  }
}

// OPTIONS for CORS
export async function OPTIONS(request: NextRequest) {
  return new NextResponse(null, {
    status: 200,
    headers: {
      'Access-Control-Allow-Origin': '*',
      'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
      'Access-Control-Allow-Headers': 'Content-Type, Authorization, x-user-id',
    },
  })
}
'''

