# 11. Rate Limiting Library - Production Security
rate_limit = '''import { NextRequest } from 'next/server'

interface RateLimitOptions {
  interval: number
  uniqueTokenPerInterval: number
}

interface RateLimitResult {
  success: boolean
  limit: number
  remaining: number
  reset: Date
}

class InMemoryRateLimit {
  private cache = new Map<string, { count: number; reset: number }>()
  private interval: number
  private limit: number

  constructor(options: RateLimitOptions) {
    this.interval = options.interval
    this.limit = options.uniqueTokenPerInterval
  }

  async check(identifier: string, limit?: number): Promise<RateLimitResult> {
    const now = Date.now()
    const windowStart = now - this.interval
    const requestLimit = limit || this.limit

    // Clean expired entries
    this.cleanup(windowStart)

    const current = this.cache.get(identifier) || { count: 0, reset: now + this.interval }

    if (current.reset < now) {
      // Reset window
      current.count = 0
      current.reset = now + this.interval
    }

    const success = current.count < requestLimit

    if (success) {
      current.count++
      this.cache.set(identifier, current)
    }

    return {
      success,
      limit: requestLimit,
      remaining: Math.max(0, requestLimit - current.count),
      reset: new Date(current.reset)
    }
  }

  private cleanup(windowStart: number) {
    for (const [key, value] of this.cache.entries()) {
      if (value.reset < windowStart) {
        this.cache.delete(key)
      }
    }
  }
}

// Production rate limiting with Redis-like interface
export class RateLimit {
  private limiter: InMemoryRateLimit

  constructor(options: RateLimitOptions) {
    this.limiter = new InMemoryRateLimit(options)
  }

  async check(identifier: string, limit?: number): Promise<RateLimitResult> {
    return this.limiter.check(identifier, limit)
  }

  // Middleware function for Next.js
  middleware(limit: number) {
    return async (req: NextRequest) => {
      const identifier = this.getIdentifier(req)
      const result = await this.check(identifier, limit)

      return {
        ...result,
        headers: {
          'X-RateLimit-Limit': result.limit.toString(),
          'X-RateLimit-Remaining': result.remaining.toString(),
          'X-RateLimit-Reset': result.reset.toISOString(),
        }
      }
    }
  }

  private getIdentifier(req: NextRequest): string {
    // Try to get the real IP address
    const forwarded = req.headers.get('x-forwarded-for')
    const realIp = req.headers.get('x-real-ip')

    if (forwarded) {
      return forwarded.split(',')[0].trim()
    }

    if (realIp) {
      return realIp
    }

    // Fallback to request IP or a default
    return req.ip || 'unknown'
  }
}

// Factory function for easy usage
export function rateLimit(options: RateLimitOptions) {
  return new RateLimit(options)
}

// Predefined rate limiters for different use cases
export const rateLimiters = {
  // API requests - 60 per minute
  api: rateLimit({
    interval: 60 * 1000,
    uniqueTokenPerInterval: 60
  }),

  // AI processing - 10 per minute (more expensive)
  ai: rateLimit({
    interval: 60 * 1000,
    uniqueTokenPerInterval: 10
  }),

  // Authentication - 5 attempts per 15 minutes
  auth: rateLimit({
    interval: 15 * 60 * 1000,
    uniqueTokenPerInterval: 5
  }),

  // Revenue tracking - 100 per hour
  revenue: rateLimit({
    interval: 60 * 60 * 1000,
    uniqueTokenPerInterval: 100
  })
}

// Enhanced rate limiting with user tiers
export class TieredRateLimit extends RateLimit {
  private tiers: Map<string, number> = new Map([
    ['free', 10],      // 10 requests per minute
    ['pro', 100],      // 100 requests per minute  
    ['enterprise', 1000] // 1000 requests per minute
  ])

  async checkWithTier(identifier: string, tier: string = 'free'): Promise<RateLimitResult> {
    const limit = this.tiers.get(tier) || this.tiers.get('free')!
    return this.check(identifier, limit)
  }

  setTierLimit(tier: string, limit: number) {
    this.tiers.set(tier, limit)
  }
}

// Export the main rate limiting function
export default rateLimit
